import { motion, AnimatePresence } from 'framer-motion';
import { useState, useEffect, createContext, useContext } from 'react';

const ToastContext = createContext(null);

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  const push = (message, type = 'info') => {
    const id = Date.now() + Math.random();
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  return (
    <ToastContext.Provider value={push}>
      {children}
      <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-2" aria-live="polite">
        <AnimatePresence>
          {toasts.map(t => (
            <motion.div
              key={t.id}
              initial={{ opacity: 0, x: 100 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 100 }}
              className={`glass rounded-xl px-5 py-3 min-w-[240px] border-l-4 ${
                t.type === 'success' ? 'border-dino-mint' :
                t.type === 'error' ? 'border-dino-danger' :
                'border-dino-accent'
              }`}
            >
              <p className="text-sm">{t.message}</p>
            </motion.div>
          ))}
        </AnimatePresence>
      </div>
    </ToastContext.Provider>
  );
}

export const useToast = () => useContext(ToastContext);

import { createContext, useContext, useState, useEffect } from 'react';

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const stored = localStorage.getItem('dinobox_user');
    if (stored) setUser(JSON.parse(stored));
  }, []);

  const register = (username, email, password) => {
    const users = JSON.parse(localStorage.getItem('dinobox_users') || '[]');
    if (users.find(u => u.email === email)) {
      throw new Error('Email already registered');
    }
    const newUser = { id: Date.now(), username, email, password };
    users.push(newUser);
    localStorage.setItem('dinobox_users', JSON.stringify(users));
    const session = { id: newUser.id, username, email };
    localStorage.setItem('dinobox_user', JSON.stringify(session));
    setUser(session);
    return session;
  };

  const login = (email, password) => {
    const users = JSON.parse(localStorage.getItem('dinobox_users') || '[]');
    const found = users.find(u => u.email === email && u.password === password);
    if (!found) throw new Error('Invalid credentials');
    const session = { id: found.id, username: found.username, email: found.email };
    localStorage.setItem('dinobox_user', JSON.stringify(session));
    setUser(session);
    return session;
  };

  const logout = () => {
    localStorage.removeItem('dinobox_user');
    setUser(null);
  };

  return (
    <AuthContext.Provider value={{ user, register, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within AuthProvider');
  return ctx;
};

import { createContext, useContext, useState, useEffect } from 'react';

const BalanceContext = createContext(null);

export function BalanceProvider({ children }) {
  const [balance, setBalance] = useState(0);

  useEffect(() => {
    const stored = localStorage.getItem('dinobox_balance');
    if (stored) setBalance(Number(stored));
  }, []);

  useEffect(() => {
    localStorage.setItem('dinobox_balance', balance);
  }, [balance]);

  const addFunds = (amount) => setBalance(b => b + amount);
  const deduct = (amount) => {
    if (balance < amount) throw new Error('Insufficient funds');
    setBalance(b => b - amount);
  };

  return (
    <BalanceContext.Provider value={{ balance, addFunds, deduct }}>
      {children}
    </BalanceContext.Provider>
  );
}

export const useBalance = () => {
  const ctx = useContext(BalanceContext);
  if (!ctx) throw new Error('useBalance must be used within BalanceProvider');
  return ctx;
};

import { createContext, useContext, useState } from 'react';

const CartContext = createContext(null);

export function CartProvider({ children }) {
  const [items, setItems] = useState([]);

  const addItem = (product) => {
    setItems(prev => {
      const existing = prev.find(i => i.id === product.id);
      if (existing) {
        return prev.map(i =>
          i.id === product.id ? { ...i, qty: i.qty + 1 } : i
        );
      }
      return [...prev, { ...product, qty: 1 }];
    });
  };

  const removeItem = (id) => setItems(prev => prev.filter(i => i.id !== id));

  const updateQty = (id, qty) => {
    if (qty <= 0) return removeItem(id);
    setItems(prev => prev.map(i => i.id === id ? { ...i, qty } : i));
  };

  const clearCart = () => setItems([]);

  const total = items.reduce((sum, i) => sum + i.productPrice * i.qty, 0);
  const count = items.reduce((sum, i) => sum + i.qty, 0);

  return (
    <CartContext.Provider value={{ items, addItem, removeItem, updateQty, clearCart, total, count }}>
      {children}
    </CartContext.Provider>
  );
}

export const useCart = () => {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error('useCart must be used within CartProvider');
  return ctx;
};

import { useState, useEffect } from 'react';

export function useLocation() {
  const [location, setLocation] = useState({ city: 'Santiago', loading: true, error: null });

  useEffect(() => {
    if (!navigator.geolocation) {
      setLocation({ city: 'Santiago', loading: false, error: null });
      return;
    }

    navigator.geolocation.getCurrentPosition(
      async (pos) => {
        try {
          const { latitude, longitude } = pos.coords;
          const res = await fetch(
            `https://nominatim.openstreetmap.org/reverse?lat=${latitude}&lon=${longitude}&format=json&zoom=10`
          );
          const data = await res.json();
          const city =
            data.address?.city ||
            data.address?.town ||
            data.address?.municipality ||
            data.address?.county ||
            'Santiago';
          setLocation({ city, loading: false, error: null });
        } catch (e) {
          setLocation({ city: 'Santiago', loading: false, error: null });
        }
      },
      () => {
        // Gracefully handle permission denied or timeout without breaking UI
        setLocation({ city: 'Santiago', loading: false, error: null });
      },
      { enableHighAccuracy: false, timeout: 8000, maximumAge: 600000 }
    );
  }, []);

  return location;
}

import { useState, useEffect, useRef } from 'react';
import api from '../services/api';

export function usePackageSimulation(orderId, initialState = 'PENDING') {
  const [state, setState] = useState(initialState);
  const [nextChangeIn, setNextChangeIn] = useState(null);
  const timerRef = useRef(null);

  // STRICT GUARD: If no ID or already finished, do absolutely nothing.
  if (!orderId || initialState === 'ARRIVED' || initialState === 'LOST') {
    return { state: initialState, nextChangeIn: null };
  }

  const skewedDelay = () => Math.round(10 + Math.pow(Math.random(), 0.5) * 50);
  const normalDelay = () => Math.round(10 + Math.random() * 50);

  useEffect(() => {
    if (!orderId || state === 'ARRIVED' || state === 'LOST') return;

    const storageKey = `dinobox_simulation_${orderId}`;
    let simData = JSON.parse(localStorage.getItem(storageKey) || 'null');

    if (!simData || simData.state !== state) {
      const delay = state === 'PENDING' ? skewedDelay() : normalDelay();
      simData = { state, nextStateTime: Date.now() + delay * 1000 };
      localStorage.setItem(storageKey, JSON.stringify(simData));
    }

    const tick = async () => {
      const currentData = JSON.parse(localStorage.getItem(storageKey));
      if (!currentData) return;

      const now = Date.now();
      const remaining = Math.max(0, Math.ceil((currentData.nextStateTime - now) / 1000));
      setNextChangeIn(remaining);

      if (now >= currentData.nextStateTime) {
        let nextState = state;

        if (state === 'PENDING') nextState = 'EN_ROUTE';
        else if (state === 'EN_ROUTE') nextState = Math.random() < 0.5 ? 'WE_HAVE_NO_IDEA' : (Math.random() < 0.66 ? 'ARRIVED' : 'LOST');
        else if (state === 'WE_HAVE_NO_IDEA') nextState = Math.random() < 0.66 ? 'ARRIVED' : 'LOST';

        if (nextState === 'ARRIVED' || nextState === 'LOST') {
          const finalData = { state: nextState, nextStateTime: null };
          localStorage.setItem(storageKey, JSON.stringify(finalData));
          setState(nextState);
          setNextChangeIn(null);

          // Update the Order entry via PUT
          try { await api.put(`/orders/${orderId}`, { currentState: nextState }); } 
          catch (e) { console.error("State update failed", e); }
          return;
        }

        const nextDelay = normalDelay();
        const newData = { state: nextState, nextStateTime: Date.now() + nextDelay * 1000 };
        localStorage.setItem(storageKey, JSON.stringify(newData));
        setState(nextState);

        // Update the Order entry via PUT
        try { await api.put(`/orders/${orderId}`, { currentState: nextState }); } 
        catch (e) { console.error("State update failed", e); }
      }
    };

    tick();
    timerRef.current = setInterval(tick, 1000);

    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [orderId, state]);

  return { state, nextChangeIn };
}

import { useState } from 'react';
import { motion } from 'framer-motion';
import { useBalance } from '../context/BalanceContext';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { useToast } from '../components/Toast';

const PRESETS = [5000, 10000, 25000, 50000, 100000];

export function Balance() {
  const { balance, addFunds } = useBalance();
  const { user } = useAuth();
  const navigate = useNavigate();
  const toast = useToast();
  const [custom, setCustom] = useState('');
  const [filling, setFilling] = useState(false);

  const formatCLP = (n) =>
    new Intl.NumberFormat('es-CL', { style: 'currency', currency: 'CLP', maximumFractionDigits: 0 }).format(n);

  const handleFill = async (amount) => {
    if (!user) {
      toast('Please sign in to fill your balance', 'error');
      navigate('/login');
      return;
    }
    if (amount <= 0) return;
    setFilling(true);
    // Simulate processing delay (2-4s)
    await new Promise(r => setTimeout(r, 2000 + Math.random() * 2000));
    addFunds(amount);
    toast(`Added ${formatCLP(amount)} to your balance`, 'success');
    setFilling(false);
    setCustom('');
  };

  return (
    <div className="max-w-3xl mx-auto px-6 py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="glass rounded-3xl p-10 text-center mb-8"
      >
        <p className="text-dino-muted text-sm mb-2">Current Balance</p>
        <motion.p
          key={balance}
          initial={{ scale: 1.1 }}
          animate={{ scale: 1 }}
          className="font-display text-6xl font-bold gradient-text mb-2"
        >
          {formatCLP(balance)}
        </motion.p>
        <p className="text-dino-muted text-xs font-mono">CLP · Chilean Peso</p>
      </motion.div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
        className="glass rounded-2xl p-8"
      >
        <h2 className="font-display text-2xl font-bold mb-6">Fill Balance</h2>

        <div className="grid grid-cols-2 md:grid-cols-3 gap-3 mb-6">
          {PRESETS.map(amt => (
            <motion.button
              key={amt}
              whileHover={{ scale: 1.03 }}
              whileTap={{ scale: 0.97 }}
              onClick={() => handleFill(amt)}
              disabled={filling}
              className="py-4 rounded-xl border border-dino-accent/30 hover:border-dino-accent
                         hover:bg-dino-accent/10 transition-all font-mono font-bold"
            >
              {formatCLP(amt)}
            </motion.button>
          ))}
        </div>

        <div className="flex gap-3">
          <input
            type="number"
            min="1000"
            step="1000"
            value={custom}
            onChange={e => setCustom(e.target.value)}
            placeholder="Custom amount (CLP)"
            aria-label="Custom amount"
            className="flex-1 px-4 py-3 rounded-xl bg-dino-bg border border-dino-accent/20
                       focus:border-dino-accent focus:outline-none font-mono"
          />
          <button
            onClick={() => handleFill(Number(custom))}
            disabled={filling || !custom}
            className="btn-primary"
          >
            {filling ? 'Processing...' : 'Add'}
          </button>
        </div>

        <p className="text-xs text-dino-muted mt-4 text-center">
          Simulated top-up · No real money involved
        </p>
      </motion.div>
    </div>
  );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useCart } from '../context/CartContext';
import { useBalance } from '../context/BalanceContext';
import { useAuth } from '../context/AuthContext';
import { useLocation as useGeoLocation } from '../hooks/useLocation';
import { packagesApi } from '../services/api';
import { useNavigate } from 'react-router-dom';
import { useToast } from '../components/Toast';

export function Cart() {
  const { items, updateQty, removeItem, clearCart, total } = useCart();
  const { balance, deduct } = useBalance();
  const { user } = useAuth();
  const geo = useGeoLocation();
  const navigate = useNavigate();
  const toast = useToast();

  const [section, setSection] = useState('');
  const [address, setAddress] = useState('');
  const [checkingOut, setCheckingOut] = useState(false);

  const formatCLP = (n) =>
    new Intl.NumberFormat('es-CL', { style: 'currency', currency: 'CLP', maximumFractionDigits: 0 }).format(n);

  const handleCheckout = async () => {
    if (!user) {
      toast('Please sign in to checkout', 'error');
      navigate('/login');
      return;
    }
    if (total > balance) {
      toast('Insufficient balance. Please top up.', 'error');
      return;
    }
    if (!section || !address) {
      toast('Please fill in section and address', 'error');
      return;
    }

    setCheckingOut(true);
    try {
      const pkg = await packagesApi.create({
        currentState: 'PENDING',
        location: `${geo.city || 'Unknown'} · ${section} · ${address}`
      });

      // Save order details (including the exact items list) for consistent display
      const orderDetails = {
        totalPaid: total,
        items: items.map(i => ({
          name: i.productName,
          qty: i.qty,
          price: i.productPrice
        }))
      };
      localStorage.setItem(`dinobox_order_${pkg.orderId}`, JSON.stringify(orderDetails));

      deduct(total);
      clearCart();
      toast('Order placed! Tracking started.', 'success');
      navigate('/orders');
    } catch (e) {
      toast('Checkout failed: ' + e.message, 'error');
    } finally {
      setCheckingOut(false);
    }
  };

  if (items.length === 0) {
    return (
      <div className="max-w-2xl mx-auto px-6 py-20 text-center">
        <motion.div initial={{ scale: 0 }} animate={{ scale: 1 }} className="text-6xl mb-6">🛒</motion.div>
        <h1 className="font-display text-3xl font-bold mb-3">Your cart is empty</h1>
        <p className="text-dino-muted mb-6">Browse our products to get started.</p>
        <button onClick={() => navigate('/products')} className="btn-primary">Browse Products</button>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-6 py-12">
      <motion.h1 initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="font-display text-4xl font-bold gradient-text mb-8">
        Your Cart
      </motion.h1>

      <div className="grid lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-3">
          <AnimatePresence>
            {items.map((item, index) => (
              <motion.div
                key={item.id ?? item.Id ?? `cart-item-${index}`}
                layout
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                className="glass rounded-xl p-4 flex items-center gap-4"
              >
                <div className="flex-1">
                  <h3 className="font-semibold">{item.productName}</h3>
                  <p className="text-xs text-dino-muted">{item.manufacturer}</p>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={() => updateQty(item.id ?? item.Id, item.qty - 1)} className="w-8 h-8 rounded-lg bg-dino-bg hover:bg-dino-accent/20 transition-colors" aria-label="Decrease quantity">−</button>
                  <span className="w-8 text-center font-mono">{item.qty}</span>
                  <button onClick={() => updateQty(item.id ?? item.Id, item.qty + 1)} className="w-8 h-8 rounded-lg bg-dino-bg hover:bg-dino-accent/20 transition-colors" aria-label="Increase quantity">+</button>
                </div>
                <p className="font-mono font-bold w-28 text-right gradient-text">
                  {formatCLP(item.productPrice * item.qty)}
                </p>
                <button onClick={() => removeItem(item.id ?? item.Id)} className="text-dino-danger hover:text-dino-danger/80 transition-colors" aria-label={`Remove ${item.productName}`}>✕</button>
              </motion.div>
            ))}
          </AnimatePresence>
        </div>

        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} className="glass rounded-2xl p-6 h-fit sticky top-24">
          <h2 className="font-display text-xl font-bold mb-4">Delivery Details</h2>

          <div className="mb-4 p-3 rounded-lg bg-dino-bg border border-dino-accent/10">
            <p className="text-xs text-dino-muted">Detected City</p>
            <p className="font-semibold">{geo.loading ? 'Detecting...' : geo.city || 'Santiago'}</p>
          </div>

          <div className="space-y-3 mb-6">
            <div>
              <label htmlFor="section" className="block text-sm text-dino-muted mb-1">Section / District</label>
              <input id="section" value={section} onChange={e => setSection(e.target.value)} placeholder="e.g. Providencia" className="w-full px-3 py-2 rounded-lg bg-dino-bg border border-dino-accent/20 focus:border-dino-accent focus:outline-none text-sm" />
            </div>
            <div>
              <label htmlFor="address" className="block text-sm text-dino-muted mb-1">Street Address</label>
              <input id="address" value={address} onChange={e => setAddress(e.target.value)} placeholder="e.g. Av. Providencia 1234" className="w-full px-3 py-2 rounded-lg bg-dino-bg border border-dino-accent/20 focus:border-dino-accent focus:outline-none text-sm" />
            </div>
          </div>

          <div className="border-t border-dino-accent/10 pt-4 mb-4">
            <div className="flex justify-between text-sm mb-2">
              <span className="text-dino-muted">Subtotal</span>
              <span className="font-mono">{formatCLP(total)}</span>
            </div>
            <div className="flex justify-between text-sm mb-2">
              <span className="text-dino-muted">Delivery</span>
              <span className="font-mono text-dino-mint">Free</span>
            </div>
            <div className="flex justify-between font-bold text-lg pt-2 border-t border-dino-accent/10">
              <span>Total</span>
              <span className="gradient-text">{formatCLP(total)}</span>
            </div>
          </div>

          <div className="text-xs text-dino-muted mb-4">
            Your balance: <span className="font-mono text-dino-mint">{formatCLP(balance)}</span>
          </div>

          <button onClick={handleCheckout} disabled={checkingOut} className="btn-primary w-full">
            {checkingOut ? 'Processing...' : 'Place Order'}
          </button>
        </motion.div>
      </div>
    </div>
  );
}

