import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { OrderTracker } from '../components/OrderTracker';
import { useAuth } from '../context/AuthContext';
import api from '../services/api'; // Use default axios instance

export function Orders() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();

  useEffect(() => {
    const loadHistory = async () => {
      if (!user) {
        setLoading(false);
        return;
      }
      try {
        // Fetch the immutable receipt history from the new backend endpoint
        const response = await api.get(`/orders/history/${user.username}`);
        setOrders(response.data);
      } catch (e) {
        console.error('Failed to load order history', e);
        setOrders([]);
      } finally {
        setLoading(false);
      }
    };

    loadHistory();
    // Poll every 15s to catch state updates on active deliveries
    const interval = setInterval(loadHistory, 15000);
    return () => clearInterval(interval);
  }, [user]);

  if (!user) {
    return (
      <div className="max-w-2xl mx-auto px-6 py-20 text-center">
        <h1 className="font-display text-3xl font-bold gradient-text mb-4">Please Sign In</h1>
        <p className="text-dino-muted">You need to be logged in to view your order history.</p>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
          className="w-12 h-12 rounded-full border-2 border-dino-accent border-t-transparent"
        />
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto px-6 py-12">
      <motion.h1
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="font-display text-4xl font-bold gradient-text mb-2"
      >
        Order History
      </motion.h1>
      <p className="text-dino-muted mb-8">A permanent record of your DinoBox purchases.</p>

      {orders.length === 0 ? (
        <div className="glass rounded-2xl p-12 text-center">
          <div className="text-5xl mb-4">📭</div>
          <p className="text-dino-muted">No past orders found. Start shopping!</p>
        </div>
      ) : (
        <div className="grid md:grid-cols-2 gap-4">
          {orders.map((o, i) => (
            <motion.div
              key={o.id ?? `order-${i}`}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
            >
              {/* Pass the receipt data to the tracker */}
              <OrderTracker 
                order={{
                  id: o.id,
                  orderId: o.packageOrderId,
                  location: 'See package details', // Could be expanded later
                  currentState: 'PENDING', // The tracker will fetch the real state via its own hook
                  totalPaid: o.totalAmount,
                  isRefunded: o.status === 'REFUNDED'
                }} 
              />
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { ProductCard } from '../components/ProductCard';
import { productsApi } from '../services/api';

export function Products() {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [filter, setFilter] = useState('ALL');

  useEffect(() => {
    productsApi.getAll()
      .then(setProducts)
      .catch(e => setError(e.message))
      .finally(() => setLoading(false));
  }, []);

  const types = ['ALL', 'FOOD', 'ELECTRONICS', 'LIQUIDS', 'ALCOHOLIC_BEVERAGES', 'BEVERAGES', 'APPLIANCES', 'OTHER'];
  const filtered = filter === 'ALL' ? products : products.filter(p => p.type === filter);

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <motion.div
          animate={{ rotate: 360 }}
          transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
          className="w-12 h-12 rounded-full border-2 border-dino-accent border-t-transparent"
        />
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-2xl mx-auto px-6 py-20 text-center">
        <p className="text-dino-danger">Failed to load products: {error}</p>
        <p className="text-dino-muted text-sm mt-2">Make sure the backend is running on port 3770.</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-6 py-12">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="mb-10"
      >
        <h1 className="font-display text-4xl font-bold gradient-text mb-2">Products</h1>
        <p className="text-dino-muted">{products.length} items available</p>
      </motion.div>

      <div className="flex flex-wrap gap-2 mb-8" role="tablist" aria-label="Filter by product type">
        {types.map(t => (
          <button
            key={t}
            role="tab"
            aria-selected={filter === t}
            onClick={() => setFilter(t)}
            className={`px-4 py-2 rounded-full text-sm transition-all ${
              filter === t
                ? 'bg-dino-accent text-white'
                : 'bg-dino-panel text-dino-muted hover:text-dino-text border border-dino-accent/20'
            }`}
          >
            {t.replace('_', ' ')}
          </button>
        ))}
      </div>

      <motion.div
        layout
        className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6"
      >
        <AnimatePresence>
          {filtered.map((p, index) => (
            <ProductCard key={p.id ?? p.Id ?? `product-${index}`} product={p} />
          ))}
        </AnimatePresence>
      </motion.div>

      {filtered.length === 0 && (
        <p className="text-center text-dino-muted py-20">No products in this category.</p>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { useAuth } from '../context/AuthContext';

export function Register() {
  const [form, setForm] = useState({ username: '', email: '', password: '' });
  const [error, setError] = useState('');
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();
    setError('');
    if (form.password.length < 6) {
      setError('Password must be at least 6 characters');
      return;
    }
    try {
      register(form.username, form.email, form.password);
      navigate('/');
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div className="min-h-[calc(100vh-80px)] flex items-center justify-center px-6">
      <motion.form
        initial={{ opacity: 0, y: 30 }}
        animate={{ opacity: 1, y: 0 }}
        onSubmit={handleSubmit}
        className="glass rounded-3xl p-10 w-full max-w-md"
      >
        <h1 className="font-display text-3xl font-bold gradient-text mb-2">Join DinoBox</h1>
        <p className="text-dino-muted text-sm mb-8">Create your account in seconds</p>

        {error && (
          <div role="alert" className="mb-4 p-3 rounded-lg bg-dino-danger/10 border border-dino-danger/30 text-dino-danger text-sm">
            {error}
          </div>
        )}

        <div className="space-y-4">
          <div>
            <label htmlFor="username" className="block text-sm text-dino-muted mb-2">Username</label>
            <input
              id="username"
              type="text"
              required
              autoComplete="username"
              value={form.username}
              onChange={e => setForm({ ...form, username: e.target.value })}
              className="w-full px-4 py-3 rounded-xl bg-dino-bg border border-dino-accent/20
                         focus:border-dino-accent focus:outline-none transition-colors"
            />
          </div>
          <div>
            <label htmlFor="email" className="block text-sm text-dino-muted mb-2">Email</label>
            <input
              id="email"
              type="email"
              required
              autoComplete="email"
              value={form.email}
              onChange={e => setForm({ ...form, email: e.target.value })}
              className="w-full px-4 py-3 rounded-xl bg-dino-bg border border-dino-accent/20
                         focus:border-dino-accent focus:outline-none transition-colors"
            />
          </div>
          <div>
            <label htmlFor="password" className="block text-sm text-dino-muted mb-2">Password</label>
            <input
              id="password"
              type="password"
              required
              autoComplete="new-password"
              value={form.password}
              onChange={e => setForm({ ...form, password: e.target.value })}
              className="w-full px-4 py-3 rounded-xl bg-dino-bg border border-dino-accent/20
                         focus:border-dino-accent focus:outline-none transition-colors"
            />
          </div>
        </div>

        <button type="submit" className="btn-primary w-full mt-8">
          Create Account
        </button>

        <p className="text-center text-sm text-dino-muted mt-6">
          Already have an account?{' '}
          <Link to="/login" className="text-dino-glow hover:underline">Sign in</Link>
        </p>
      </motion.form>
    </div>
  );
}

import axios from 'axios';

const api = axios.create({
  baseURL: '/api/v1',
  timeout: 10000,
  headers: { 'Content-Type': 'application/json' }
});

export const productsApi = {
  getAll: () => api.get('/products').then(r => r.data),
  getById: (id) => api.get(`/products/${id}`).then(r => r.data),
  create: (product) => api.post('/products', product).then(r => r.data)
};

export const packagesApi = {
  getAll: () => api.get('/Packages').then(r => r.data),
  getById: (id) => api.get(`/Packages/${id}`).then(r => r.data),
  create: (pkg) => api.post('/Packages', pkg).then(r => r.data),
  update: (id, pkg) => api.put(`/Packages/${id}`, pkg).then(r => r.data)
};

export default api;

