      </AuthProvider>
    </BrowserRouter>
  );
}

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: dark;
}

* {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Space Grotesk', system-ui, sans-serif;
  background: #0a0a0f;
  overflow-x: hidden;
}

/* Focus styles for accessibility */
:focus-visible {
  outline: 2px solid #7c5cff;
  outline-offset: 3px;
  border-radius: 4px;
}

/* Skip link for accessibility */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: #7c5cff;
  color: white;
  padding: 8px 16px;
  z-index: 100;
  transition: top 0.2s;
}
.skip-link:focus {
  top: 0;
}

/* Custom scrollbar */
::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-track { background: #0a0a0f; }
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #7c5cff, #34d399);
  border-radius: 5px;
}

/* Glassmorphism panel */
.glass {
  background: rgba(18, 18, 26, 0.7);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(124, 92, 255, 0.15);
}

/* Gradient text */
.gradient-text {
  background: linear-gradient(135deg, #a78bfa 0%, #34d399 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

/* Button base */
.btn {
  @apply px-6 py-3 rounded-xl font-medium transition-all duration-300
         focus-visible:outline-2 focus-visible:outline-offset-2;
}
.btn-primary {
  background: linear-gradient(135deg, #7c5cff 0%, #a78bfa 100%);
  color: white;
  box-shadow: 0 4px 20px rgba(124, 92, 255, 0.4);
}
.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(124, 92, 255, 0.6);
}
.btn-primary:active { transform: translateY(0); }
.btn-primary:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

